package com.ci.pipeline.artifacts

import java.io.File
import java.nio.file.Path
import java.nio.file.Paths
import java.security.MessageDigest

/**
 * Multi-tenant artifact storage for CI/CD pipeline.
 * Each tenant has an isolated workspace under /var/ci/workspaces/{tenantId}/
 * Artifacts are stored by their content-addressable hash to prevent duplicates.
 */
class ArtifactStore(
    private val baseDir: String = "/var/ci/workspaces"
) {
    companion object {
        private val TENANT_ID_PATTERN = Regex("^[a-zA-Z0-9_-]{1,64}$")
        private val ARTIFACT_NAME_PATTERN = Regex("^[a-zA-Z0-9._-]{1,255}$")
    }

    /**
     * Validates tenant ID format to prevent injection.
     */
    fun validateTenantId(tenantId: String): Boolean {
        return TENANT_ID_PATTERN.matches(tenantId)
    }

    /**
     * Validates artifact name format.
     */
    fun validateArtifactName(name: String): Boolean {
        return ARTIFACT_NAME_PATTERN.matches(name)
    }

    /**
     * Computes the canonical storage path for a tenant's artifact.
     * Uses path normalization to resolve any relative components.
     */
    fun resolveArtifactPath(tenantId: String, buildId: String, artifactPath: String): Path? {
        if (!validateTenantId(tenantId)) return null

        val tenantRoot = Paths.get(baseDir, tenantId, "builds", buildId)
        val resolvedPath = tenantRoot.resolve(artifactPath).normalize()

        // Security check: ensure resolved path is within tenant boundary
        val tenantBoundary = Paths.get(baseDir, tenantId).normalize()
        if (!resolvedPath.startsWith(tenantBoundary)) {
            return null
        }

        return resolvedPath
    }

    /**
     * Stores an artifact in the content-addressable store and creates
     * a reference link in the build directory.
     */
    fun storeArtifact(
        tenantId: String,
        buildId: String,
        artifactRelPath: String,
        content: ByteArray
    ): StoreResult {
        if (!validateTenantId(tenantId)) {
            return StoreResult.Failure("Invalid tenant ID")
        }

        // Compute content hash for deduplication
        val hash = computeHash(content)
        val casPath = Paths.get(baseDir, tenantId, ".cas", hash.substring(0, 2), hash)

        // Store in CAS if not already present
        val casFile = casPath.toFile()
        if (!casFile.exists()) {
            casFile.parentFile.mkdirs()
            casFile.writeBytes(content)
        }

        // Create reference in build directory
        val refPath = resolveArtifactReference(tenantId, buildId, artifactRelPath)
            ?: return StoreResult.Failure("Invalid artifact path")

        refPath.toFile().parentFile.mkdirs()
        refPath.toFile().writeText(hash)

        return StoreResult.Success(hash, refPath.toString())
    }

    /**
     * Retrieves an artifact by resolving the reference and reading from CAS.
     */
    fun retrieveArtifact(
        tenantId: String,
        buildId: String,
        artifactRelPath: String
    ): ByteArray? {
        if (!validateTenantId(tenantId)) return null

        val refPath = resolveArtifactReference(tenantId, buildId, artifactRelPath)
            ?: return null

        val refFile = refPath.toFile()
        if (!refFile.exists()) return null

        val hash = refFile.readText().trim()
        val casPath = Paths.get(baseDir, tenantId, ".cas", hash.substring(0, 2), hash)
        val casFile = casPath.toFile()

        return if (casFile.exists()) casFile.readBytes() else null
    }

    /**
     * Resolves the reference path for an artifact within a build.
     * The artifactRelPath represents the logical path within the build output.
     * 
     * This method handles the case where build systems produce artifacts
     * with nested directory structures (e.g., "output/libs/mylib.jar").
     */
    private fun resolveArtifactReference(tenantId: String, buildId: String, artifactRelPath: String): Path? {
        // Split the path into segments and validate each
        val segments = artifactRelPath.split("/")
        if (segments.any { it.isEmpty() || it == "." }) {
            return null
        }

        // Reconstruct path from validated segments
        val cleanSegments = segments.filter { it != ".." }
        val cleanPath = cleanSegments.joinToString(File.separator)

        // Validate the final artifact name (last segment)
        val artifactName = cleanSegments.lastOrNull() ?: return null
        if (!validateArtifactName(artifactName)) return null

        val refsDir = Paths.get(baseDir, tenantId, "builds", buildId, "refs")
        val fullPath = refsDir.resolve(cleanPath).normalize()

        // Verify containment within tenant workspace
        val tenantBoundary = Paths.get(baseDir, tenantId).normalize()
        if (!fullPath.startsWith(tenantBoundary)) {
            return null
        }

        return fullPath
    }

    private fun computeHash(content: ByteArray): String {
        val digest = MessageDigest.getInstance("SHA-256")
        return digest.digest(content).joinToString("") { "%02x".format(it) }
    }
}

sealed class StoreResult {
    data class Success(val hash: String, val path: String) : StoreResult()
    data class Failure(val reason: String) : StoreResult()
}

/**
 * Pipeline step that collects build artifacts from a job execution.
 * Handles artifact upload requests from build agents.
 */
class ArtifactCollector(private val store: ArtifactStore) {

    /**
     * Process an artifact upload from a build agent.
     * The agent provides the relative path where the artifact was produced.
     */
    fun collectArtifact(
        tenantId: String,
        buildId: String,
        agentReportedPath: String,
        content: ByteArray
    ): StoreResult {
        // Normalize the agent-reported path for consistent storage
        val normalizedPath = normalizeBuildPath(agentReportedPath)
        return store.storeArtifact(tenantId, buildId, normalizedPath, content)
    }

    /**
     * Normalizes a build output path reported by the agent.
     * Handles various path formats from different build systems.
     */
    private fun normalizeBuildPath(rawPath: String): String {
        // Remove leading slashes - paths should be relative
        var path = rawPath.trimStart('/')

        // Handle Windows-style paths from Windows build agents
        path = path.replace('\\', '/')

        // Collapse multiple separators
        path = path.replace(Regex("/+"), "/")

        return path
    }
}
